import { NextResponse } from 'next/server';
import type { NextRequest } from 'next/server';

export function middleware(request: NextRequest) {
    // 사용자가 /admin 또는 그 하위 경로로 접근할 때
    if (request.nextUrl.pathname.startsWith('/admin')) {
        // 1. 브라우저에 로그인 세션 쿠키(예: JSESSIONID 나 커스텀 토큰)가 있는지 확인합니다.
        // 현재 프론트엔드 로그인 TODO 처리가 안되어 있으므로, 아주 간단히 JSESSIONID 유무로 확인합니다.
        const isAuthenticated = request.cookies.has('JSESSIONID'); // 스프링 웹 기본 세션 쿠키 이름

        // 로그인 상태 쿠키가 없다면 (즉, 로그아웃 상태라면)
        if (!isAuthenticated) {
            // 강제로 방금 만든 /login 화면으로 내쫓습니다(리다이렉트)
            return NextResponse.redirect(new URL('/login', request.url));
        }
    }

    // 만약 로그인 되어있거나 다른 일반 페이지로 가는 거라면 그대로 통과시킵니다.
    return NextResponse.next();
}

// 이 미들웨어가 작동할 경로들을 설정합니다.
export const config = {
    matcher: ['/admin/:path*'],
};
